// Get user data from Webhook
const body = $('Webhook').first().json.body;
const uid = parseInt(body.user_id || 0, 10);
const uname = body.user_name || '';
const original = body.message;

// Parse LLM classification
let classification = { isComplex: true };
try {
  const raw = $input.first().json.text || '';
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) {
    classification = JSON.parse(raw.slice(start, end + 1));
  }
} catch(e) {}

const isComplex = !!classification.isComplex;
const table = classification.table || '';
const filters = classification.filters || {};
let query = null;

if (!isComplex && table) {
  if (filters.count) {
    if (table === 'test_cases') { query = `SELECT COUNT(*) as total FROM test_cases tc JOIN user_project_assignment upa ON tc.project_id = upa.project_id WHERE upa.user_id = ${uid};`; }
    else if (table === 'defects') { query = `SELECT COUNT(*) as total FROM defects d JOIN user_project_assignment upa ON d.project_id = upa.project_id WHERE upa.user_id = ${uid};`; }
    else if (table === 'projects') { query = `SELECT COUNT(*) as total FROM projects p JOIN user_project_assignment upa ON p.id = upa.project_id WHERE upa.user_id = ${uid};`; }
    else if (table === 'requirements') { query = `SELECT COUNT(*) as total FROM requirements r JOIN user_project_assignment upa ON r.project_id = upa.project_id WHERE upa.user_id = ${uid};`; }
  } else if (table === 'test_cases') {
    const sf = filters.status ? ` AND tc.status = '${filters.status}'` : '';
    query = `SELECT tc.id, tc.title, tc.status, tc.test_type, p.name as project FROM test_cases tc JOIN projects p ON tc.project_id = p.id JOIN user_project_assignment upa ON p.id = upa.project_id WHERE upa.user_id = ${uid}${sf} ORDER BY tc.id DESC LIMIT 100;`;
  } else if (table === 'defects') {
    const sf = filters.status ? ` AND d.status = '${filters.status}'` : '';
    const sevf = filters.severity ? ` AND d.severity = '${filters.severity}'` : '';
    query = `SELECT d.id, d.title, d.severity, d.status, p.name as project FROM defects d JOIN projects p ON d.project_id = p.id JOIN user_project_assignment upa ON p.id = upa.project_id WHERE upa.user_id = ${uid}${sf}${sevf} ORDER BY d.id DESC LIMIT 100;`;
  } else if (table === 'projects') {
    const sf = filters.status ? ` AND p.status = '${filters.status}'` : '';
    query = `SELECT DISTINCT p.id, p.name, p.description, p.status FROM projects p JOIN user_project_assignment upa ON p.id = upa.project_id WHERE upa.user_id = ${uid}${sf} LIMIT 100;`;
  } else if (table === 'requirements') {
    query = `SELECT r.id, r.title, r.description, p.name as project FROM requirements r JOIN projects p ON r.project_id = p.id JOIN user_project_assignment upa ON p.id = upa.project_id WHERE upa.user_id = ${uid} LIMIT 100;`;
  } else if (table === 'releases') {
    query = `SELECT r.id, r.version, r.description, p.name as project FROM releases r JOIN projects p ON r.project_id = p.id JOIN user_project_assignment upa ON p.id = upa.project_id WHERE upa.user_id = ${uid} LIMIT 100;`;
  }
}

return [{ json: { query, uid, uname, original_message: original, isComplex: !!(isComplex || !query) } }];

const rows = $input.all().map(r => r.json);
const msg = $('Generate SQL').first().json.original_message;

if (rows.length === 0) {
  return [{ json: { response: `No results found for: "${msg}"` } }];
}

if (rows[0].total !== undefined) {
  return [{ json: { response: `**Total: ${rows[0].total}**` } }];
}

const formatted = rows.map((r, i) => {
  const lines = Object.entries(r)
    .map(([k, v]) => `  - **${k}**: ${v}`)
    .join('\n');
  return `**${i + 1}.** ${r.title || r.name || r.version || ''}\n${lines}`;
}).join('\n\n');

return [{ json: { response: `Found **${rows.length}** result(s):\n\n${formatted}` } }];

parameters.text:
=You are a query classifier for a QA platform database.

SCHEMA:
- test_cases: id, project_id, title, status (pass/fail/ongoing/blocked/retest), test_type
- defects: id, project_id, title, severity (low/medium/high/critical), status (open/in_progress/resolved/closed)
- projects: id, name, description, status (on-track/at-risk/delayed/completed)
- requirements: id, project_id, title, description
- releases: id, project_id, version, description

Classify the user's question and respond ONLY with valid JSON — no markdown, no extra text.

Simple (single table + optional filter): {"isComplex": false, "table": "TABLE_NAME", "filters": {}}
Complex (multi-table, aggregation, negation): {"isComplex": true}

Examples:
"which test cases failed?" -> {"isComplex": false, "table": "test_cases", "filters": {"status": "fail"}}
"list all defects" -> {"isComplex": false, "table": "defects", "filters": {}}
"how many test cases do I have?" -> {"isComplex": false, "table": "test_cases", "filters": {"count": true}}
"which requirements have no test cases?" -> {"isComplex": true}
"show high severity defects" -> {"isComplex": false, "table": "defects", "filters": {"severity": "high"}}
"list delayed projects" -> {"isComplex": false, "table": "projects", "filters": {"status": "delayed"}}

User question: {{ $('Webhook').first().json.body.message }}
